func Map[T, R any](ctx context.Context, in []T, workers int, fn ...) ([]R, error) {
    if workers < 1 { workers = 1 }
    n := len(in)
    if n == 0 { return nil, nil } // out := make([]R, 0)

    type result struct { r R; err error; i int }
    jobs := make(chan int, workers)
    results := make(chan result)
    stop := make(chan struct{}) // closed when we should stop dispatching

    var wg sync.WaitGroup
    for w := 0; w < workers; w++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for i := range jobs {
                r, err := fn(ctx, in[i])
                select {
                case results <- result{r, err, i}:
                case <-stop:
                    // Map is shutting down; drop the result
                }
            }
        }()
    }
    // Dispatcher
    go func() {
        defer close(jobs)
        for i := 0; i < n; i++ {
            select {
            case jobs <- i:
            case <-stop:
                return
            }
        }
    }()

    out := make([]R, n)
    var (
        failed      bool
        firstIdx    int = -1
        firstErr    error
        remaining   int = n
