	Index int
	Err   error
}

func (e *IndexError) Error() string { return fmt.Sprintf("pool: input %d: %v", e.Index, e.Err) }
func (e *IndexError) Unwrap() error { return e.Err }

// Map calls fn on every element of in using at most workers goroutines
// (workers < 1 means 1) and returns the results in input order: out[i] is
// fn(ctx, in[i]).
//
// If any call returns an error, Map stops handing out new inputs, waits for
// running calls to return, and returns a nil slice and an *IndexError for the
// failing input with the LOWEST index among those that failed.
//
// If ctx is cancelled, Map stops handing out new inputs, waits for running
// calls to return, and returns ctx.Err() (unless a call failed first, in which
// case the rule above applies). Map never leaks goroutines: when it returns,
// all workers have exited.
func Map[T, R any](ctx context.Context, in []T, workers int, fn func(context.Context, T) (R, error)) ([]R, error) {
	if workers < 1 {
		workers = 1
	}
	n := len(in)
	out := make([]R, n)
	if n == 0 {
		return out, nil
	}

	type result struct {
		r   R
		err error
		i   int
	}
	jobs := make(chan int) // unbuffered: a job counts as handed out only when a worker takes it
	results := make(chan result)
	stop := make(chan struct{}) // closed once every result has been accounted for
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case i, ok := <-jobs:
					if !ok {
						return
					}
					r, err := fn(ctx, in[i])
					results <- result{r, err, i}
				case <-stop:
					return
				}
			}
		}()
	}

	ctxDone := ctx.Err() != nil
	next := 0       // next input not yet handed out
	inFlight := 0   // handed out but whose result has not arrived
	failIdx := -1   // lowest index of a failed call
	failErr error   // its error
	failFirst := false

	for next < n || inFlight > 0 {
		if next < n && !ctxDone {
			select {
			case jobs <- next:
				next++
				inFlight++
				continue
			case res := <-results:
				inFlight--
				if res.err != nil {
					if failIdx == -1 || res.i < failIdx {
						failIdx, failErr = res.i, res.err
					}
					if !ctxDone {
						failFirst = true
					}
				} else {
					out[res.i] = res.r
				}
				continue
			case <-ctx.Done():
				ctxDone = true
			}
		}
		res := <-results
		inFlight--
		if res.err != nil {
			if failIdx == -1 || res.i < failIdx {
				failIdx, failErr = res.i, res.err
			}
			if !ctxDone {
				failFirst = true
			}
		} else {
			out[res.i] = res.r
		}
	}
	close(stop) // no worker can be blocked anymore; let them exit
	close(jobs)
	wg.Wait() // guarantee no leaked goroutines before returning

	switch {
	case failIdx >= 0 && (failFirst || !ctxDone):
		return nil, &IndexError{Index: failIdx, Err: failErr}
	case ctxDone:
		return nil, ctx.Err()
	default:
		return out, nil
	}
}
"}

